$effFile='C:\Users\ADMINI~1\AppData\Local\Temp\dsh-spill-wI8dAp\session-03b04285887b\d842292fc3cc-mcp_gateway.txt'

function Parse-Table($path){
  $rows=@()
  foreach($line in (Get-Content $path)){
    if($line -match '^\|\s*(\d+)\s*\|' -or $line -match '^\|\s*(bug|task)\s*\|'){
      $cells=$line.Trim('|').Split('|') | ForEach-Object { $_.Trim() }
      $rows+=,$cells
    }
  }
  return $rows
}

# Bugs: id,title,toTask,project,execution,module,product,openedBy,resolvedBy,resolvedDate,status
$bugs=@(Parse-Table $bugFile) | Where-Object { $_[0] -match '^\d+$' -and $_[8] -eq 'tiany' }
# Efforts: id,objectType,objectID,account,work,date,consumed,product,project,execution
$efforts=@(Parse-Table $effFile) | Where-Object { $_[0] -match '^\d+$' -and $_[3] -eq 'tiany' -and $_[5] -match '^2026-11-' }

"=== Per-day bug counts (tiany) ==="
$bugs | Group-Object { $_[9].Substring(0,10) } | Sort-Object Name | ForEach-Object {
  $day=$_.Name
  $untransferred=($_ .Group | Where-Object { $_[2] -eq '0' }).Count
  "  $day : $($_.Count) bugs, $untransferred with toTask=0"
}
"=== Per-day tiany effort ==="
$efforts | Group-Object { $_[5] } | Sort-Object Name | ForEach-Object {
  $sum=($_.Group | ForEach-Object { [double]$_[6] } | Measure-Object -Sum).Sum
  "  $($_.Name) : $($_.Count) rows, total $sum"
}

